function renderHistoryTable() {
 const monitoring=state.user.role==='boh';
 const all=state.documents.filter(d=>d.kind==='Standing Instruction'&&historyOutcome(d));
 const query=state.historySearch.trim().toLocaleLowerCase('id-ID');
 let docs=all.filter(d=>(state.historyResult==='all'||historyOutcome(d).result===state.historyResult)&&`${d.customer_name} ${d.cif} ${d.id}`.toLocaleLowerCase('id-ID').includes(query));
 const total=docs.length,pages=Math.max(1,Math.ceil(total/5));state.page=Math.max(1,Math.min(state.page,pages));const start=(state.page-1)*5;docs=docs.slice(start,start+5);
 $('#doc-table').innerHTML=docs.length?`<div class="table-wrap"><table class="table history-table"><thead><tr><th>Nasabah / Dokumen</th><th>Nominal transaksi</th><th>Status</th><th>Terakhir diperbarui</th>${monitoring?'':'<th>Dokumen</th>'}</tr></thead><tbody>${docs.map(d=>{const outcome=historyOutcome(d);return `<tr><td><strong>${esc(d.customer_name)}</strong><small class="mono">${esc(d.id)}</small><small>CIF ${esc(d.cif)}</small></td><td><strong class="amount">${rupiah(d.nominal)}</strong></td><td><span class="badge history-${outcome.result}">${outcome.label}</span>${outcome.result==='failure'?`<small>${outcome.reason}</small>`:''}</td><td>${date(d.updated)}</td>${monitoring?'':`<td><div class="actions history-actions"><button class="btn small" data-route="doc/${esc(d.id)}">Lihat detail</button>${outcome.result==='success'?`<button class="btn primary small" data-action="download-execution-pdf" data-id="${esc(d.id)}">${icon('download')} Unduh PDF</button>`:''}</div></td>`}</tr>`;}).join('')}</tbody></table></div><div class="table-footer"><span aria-live="polite">Menampilkan ${start+1}–${start+docs.length} dari ${total} dokumen SI</span>${pages>1?`<div class="table-pagination" role="group" aria-label="Halaman history"><button class="btn small" data-action="page-prev" ${state.page===1?'disabled':''}>${icon('left')} Sebelumnya</button><span>Halaman ${state.page} dari ${pages}</span><button class="btn small" data-action="page-next" ${state.page===pages?'disabled':''}>Berikutnya ${icon('arrow')}</button></div>`:''}</div>`:empty(all.length?'Tidak ada history yang cocok':'Belum ada history SI',all.length?'Ubah pencarian atau filter hasil.':'SI yang disetujui, ditolak, atau dibatalkan akan muncul di sini.');
}
function renderDocumentForm(doc=null) {
 const revision=!!doc;
 if(revision&&doc.sol_status!=='revision_requested'){$('#main').innerHTML=notice('Pengajuan ini belum diminta untuk direvisi.','warn');return;}
 const chosen=revision?(state.customers.find(c=>c.cif===doc.cif)||{cif:doc.cif,name:doc.customer_name,account:doc.account,person:doc.person,email:doc.email}):null;
 $('#main').innerHTML=`${head(revision?'TINDAK LANJUT SOL':'INISIASI DOKUMEN',revision?'Revisi surat':'Tambah Pengajuan',revision?`${esc(doc.id)} · Surat revisi akan dikirim untuk konfirmasi ulang.`:'Lengkapi detail, unggah surat, lalu kirim konfirmasi kepada nasabah.',`<button class="btn" data-route="${revision?'doc/'+esc(doc.id):'documents'}">${icon('left')} Kembali</button>`)}${revision?`<div class="stack">${notice(`<strong>Catatan SOL</strong><p>${esc(doc.sol_notes)}</p>`,'warn')}${notice('Revisi surat memerlukan konfirmasi baru. Tautan sebelumnya otomatis dibatalkan.')}</div>`:''}<div class="form-layout"><form class="card" id="document-form"><section class="form-section"><div class="section-title"><span class="step-number">01</span><div><h3>Data Nasabah</h3></div></div><div class="field"><label for="customer-search">Nasabah / CIF <span class="required">*</span></label><div class="customer-picker"><div class="search-box">${icon('search')}<input id="customer-search" class="input" type="text" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="customer-options" autocomplete="off" placeholder="Cari dan pilih nama nasabah atau CIF…" value="${chosen?esc(chosen.cif+' · '+chosen.name):''}" ${revision?'readonly':'required'}><input id="customer-select" type="hidden" name="cif" value="${doc?esc(doc.cif):''}"></div><div id="customer-options" class="customer-options" role="listbox" aria-label="Hasil pencarian nasabah" hidden></div></div>${!revision?'<small id="customer-match-count" aria-live="polite"></small>':''}</div><div id="customer-summary"></div></section><section class="form-section"><div class="section-title"><span class="step-number">02</span><div><h3>Detail transaksi</h3></div></div><div class="form-grid"><div class="field"><label for="doc-kind">Jenis dokumen <span class="required">*</span></label><select id="doc-kind" name="kind"><option ${doc?.kind==='Standing Instruction'?'selected':''}>Standing Instruction</option><option ${doc?.kind==='Warkat'?'selected':''}>Warkat</option></select></div><div class="field"><label for="doc-nominal">Nominal transaksi (Rp) <span class="required">*</span></label><input id="doc-nominal" name="nominal" type="text" inputmode="numeric" placeholder="Contoh: 250.000.000" value="${doc?new Intl.NumberFormat('id-ID').format(doc.nominal):''}" required></div><div class="field"><label for="doc-destination-account">Rekening tujuan <span class="required">*</span></label><input id="doc-destination-account" name="destination_account" type="text" inputmode="numeric" pattern="[0-9]{15}" minlength="15" maxlength="15" title="Nomor rekening BRI tepat 15 digit angka" placeholder="15 digit rekening BRI" value="${esc(doc?.destination_account||'')}" required></div><div class="field"><label for="doc-destination-name">Atas nama rekening tujuan <span class="required">*</span></label><input id="doc-destination-name" name="destination_name" type="text" maxlength="250" placeholder="Nama pemilik rekening tujuan" value="${esc(doc?.destination_name||'')}" required></div><div class="field span-2"><label for="doc-description">Keterangan transaksi</label><textarea id="doc-description" name="description" maxlength="1500" placeholder="Tujuan atau keterangan yang perlu diketahui nasabah…">${esc(doc?.description||'')}</textarea></div>${revision?'<div class="field span-2"><label for="revision-notes">Ringkasan perbaikan <span class="required">*</span></label><textarea id="revision-notes" name="notes" maxlength="1500" placeholder="Jelaskan bagian surat yang telah diperbaiki…" required></textarea></div>':''}</div></section><section class="form-section"><div class="section-title"><span class="step-number">03</span><div><h3>${revision?'Unggah surat hasil revisi':'Unggah surat'}</h3></div></div><div class="upload-area"><div class="upload-icon">${icon('upload')}</div><div class="upload-copy"><p>PDF, JPG, atau PNG · Maksimal 5 MB</p></div><button type="button" class="btn primary" data-action="choose-file">${icon('plus')} Pilih surat</button><input type="file" class="visually-hidden" id="doc-file" aria-label="Unggah surat transaksi" aria-required="true" accept=".pdf,.jpg,.jpeg,.png"><div id="file-status" class="file-status" aria-live="polite"></div></div></section><div class="form-bottom"><label class="check"><input type="checkbox" id="doc-ack" required><span>Saya telah memeriksa data nasabah, alamat email, nominal transaksi, rekening tujuan, dan surat yang akan dikirim.</span></label><div id="form-error" class="error-message" role="alert"></div><div class="form-submit"><small class="muted">${state.config.mail_mode==='console'?'Email tersedia di kotak email lokal.':'Email dikirim otomatis ke nasabah.'}</small><button type="submit" class="btn primary">${icon('mail')} ${revision?'Kirim surat revisi':'Kirim konfirmasi'}</button></div></div></form></div>`;
 const select=$('#customer-select');
 if(!revision)setupCustomerPicker();
 if(chosen)showCustomer(chosen);
 $('#doc-nominal').addEventListener('input',e=>{const digits=e.target.value.replace(/\D/g,'');e.target.value=digits?new Intl.NumberFormat('id-ID').format(Number(digits)):'';});
 $('#doc-file').addEventListener('change',e=>{const f=e.target.files[0];const valid=!f||f.size<=5*1024*1024;$('#file-status').textContent=f?(valid?`${f.name} · ${(f.size/1024/1024).toFixed(2)} MB`:'File melebihi batas 5 MB. Pilih surat lain.'):'';e.target.setCustomValidity(valid?'':'File maksimal 5 MB.');$('.upload-area').classList.toggle('has-file',!!f&&valid);$('[data-action="choose-file"]').innerHTML=icon('upload')+(f?' Ganti surat':' Pilih surat');});
 $('#document-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('button[type=submit]',e.target);button.disabled=true;$('#form-error').textContent='';try{const file=$('#doc-file').files[0];if(!file||file.size>5*1024*1024)throw new Error('Pilih surat PDF, JPG, atau PNG berukuran maksimal 5 MB.');const nominal=Number($('#doc-nominal').value.replace(/\D/g,''));if(!Number.isSafeInteger(nominal)||nominal<=0)throw new Error('Masukkan nominal lebih dari Rp0, tanpa desimal.');const file64=await fileBase64(file);const payload={cif:doc?.cif||select.value,kind:$('#doc-kind').value,nominal,destination_account:$('#doc-destination-account').value.trim(),destination_name:$('#doc-destination-name').value.trim(),description:$('#doc-description').value,file:{name:file.name,base64:file64}};if(revision){payload.version=doc.version;payload.notes=$('#revision-notes').value;}showDialog('Periksa sebelum mengirim',`<p>Konfirmasi untuk <strong>${esc(doc?.customer_name||state.customers.find(c=>c.cif===select.value)?.name)}</strong> akan dibuat dengan nominal <strong>${rupiah(nominal)}</strong>.</p><p>Rekening tujuan: <strong>${esc(payload.destination_account)}</strong><br>Atas nama: <strong>${esc(payload.destination_name)}</strong></p><p>${revision?'Nasabah perlu memberikan keputusan baru untuk surat revisi ini.':'Pastikan email penerima dan surat sudah sesuai.'}</p>`,async()=>{button.disabled=true;try{const result=await api(revision?'/documents/'+doc.id+'/revise':'/documents',payload);await refreshData();toast(revision?'Surat revisi masuk antrean email.':'Pengajuan dibuat dan email masuk antrean.');go('doc/'+result.id);}catch(err){$('#form-error').textContent=err.message;button.disabled=false;throw err;}},'Kirim konfirmasi');button.disabled=false;}catch(err){$('#form-error').textContent=err.message;button.disabled=false;}});
}
function setupCustomerPicker() {
 const input=$('#customer-search'), value=$('#customer-select'), list=$('#customer-options');
 let matches=[], active=-1;
 const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1;};
 const highlight=()=>{list.querySelectorAll('[role="option"]').forEach((option,i)=>{option.classList.toggle('highlighted',i===active);option.setAttribute('aria-selected',String(i===active));});if(active>=0){input.setAttribute('aria-activedescendant','customer-option-'+active);list.children[active]?.scrollIntoView({block:'nearest'});}else input.removeAttribute('aria-activedescendant');};
 const render=(query)=>{const q=query.trim().toLocaleLowerCase('id-ID');const all=state.customers.filter(c=>c.name.toLocaleLowerCase('id-ID').includes(q)||c.cif.includes(q));matches=all.slice(0,50);active=-1;list.innerHTML=matches.length?matches.map((c,i)=>`<button type="button" role="option" aria-selected="false" tabindex="-1" id="customer-option-${i}" data-index="${i}"><strong>${esc(c.name)}</strong><span>CIF ${esc(c.cif)}</span></button>`).join(''):'<div class="customer-no-results">Tidak ada nasabah yang cocok.</div>';list.hidden=false;input.setAttribute('aria-expanded','true');input.removeAttribute('aria-activedescendant');$('#customer-match-count').textContent=all.length>50?all.length+' nasabah ditemukan. Ketik lebih spesifik untuk mempersempit hasil.':all.length===0?'Nasabah belum terdaftar? Minta SOL menambahkan data nasabah terlebih dahulu.':'';};
 const choose=(index)=>{const c=matches[index];if(!c)return;value.value=c.cif;input.value=c.cif+' · '+c.name;input.setCustomValidity('');showCustomer(c);$('#customer-match-count').textContent='';close();};
 input.addEventListener('focus',()=>render(value.value?'':input.value));
 input.addEventListener('input',()=>{value.value='';input.setCustomValidity('Pilih nasabah dari hasil pencarian.');showCustomer(null);render(input.value);});
 input.addEventListener('keydown',e=>{if(e.key==='Escape'){close();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(list.hidden)render(value.value?'':input.value);if(matches.length){active=active<0?(e.key==='ArrowDown'?0:matches.length-1):(active+(e.key==='ArrowDown'?1:-1)+matches.length)%matches.length;highlight();}}else if(e.key==='Enter'&&!list.hidden){e.preventDefault();choose(active<0?0:active);}else if(e.key==='Tab')close();});
 input.addEventListener('blur',close);
 list.addEventListener('pointerdown',e=>{if(e.target.closest('[role="option"]'))e.preventDefault();});
 list.addEventListener('click',e=>{const option=e.target.closest('[data-index]');if(option)choose(Number(option.dataset.index));});
 input.setCustomValidity('Pilih nasabah dari hasil pencarian.');
}
function showCustomer(c) {$('#customer-summary').innerHTML=c?`<div class="customer-summary"><div><label>Nama nasabah</label><strong>${esc(c.name)}</strong></div><div><label>Nomor rekening</label><strong>${esc(c.account)}</strong></div><div><label>Jabatan</label><strong>${esc(c.person)}</strong></div><div><label>Email penerima</label><strong>${esc(c.email)}</strong></div></div>`:'';}
function fileBase64(file) {return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('File tidak dapat dibaca.'));reader.readAsDataURL(file);});}
function renderDetail() {
 const d=state.detail;const sol=state.user.role==='sol';const ready=d.sol_status==='pending'&&d.customer_status!=='pending';
 $('#main').innerHTML=`${head('DETAIL PENGAJUAN',esc(d.customer_name),`${esc(d.id)} · Dibuat ${date(d.created)}`,`<button class="btn" data-route="documents">${icon('left')} Kembali</button>`)}<div class="card status-flow"><div class="status-step">${icon('file')}<strong>01 · Pengajuan petugas</strong>${badge('confirmed','Surat diunggah')}<span class="muted">${esc(d.maker_name)}</span></div><div class="status-step">${icon('mail')}<strong>02 · Konfirmasi nasabah</strong>${badge(d.customer_status,labels[d.customer_status])}<span class="muted">${esc(d.person)}</span></div><div class="status-step">${icon('shield')}<strong>03 · Pemeriksaan SOL</strong>${badge(d.sol_status,solLabels[d.sol_status])}<span class="muted">${d.sol_status==='pending'?'Keputusan akhir pengajuan':'Keputusan tercatat di riwayat aktivitas'}</span></div></div><br>${d.sol_status==='approved'?`<section class="card card-pad execution-output"><div><h2>Dokumen pelaksanaan siap diunduh</h2><p class="muted">Surat konfirmasi, riwayat persetujuan, dan dokumen unggahan dalam satu PDF.</p></div><button class="btn primary" data-action="download-execution-pdf">${icon('download')} Unduh PDF pelaksanaan</button></section><br>`:''}<div class="detail-layout"><div class="stack"><section class="card"><div class="card-head"><h2>Informasi surat</h2>${statusBadge(d)}</div><div class="card-pad"><div class="detail-grid"><div><label>Nomor pengajuan</label><strong>${esc(d.id)}</strong></div><div><label>Dibuat pada</label><strong>${date(d.created)}</strong></div><div class="span-2"><label>Nominal transaksi</label><strong class="amount">${rupiah(d.nominal)}</strong></div><div><label>Jenis dokumen</label><strong>${esc(d.kind)}</strong></div><div><label>CIF / Nomor rekening</label><strong>${esc(d.cif)} / ${esc(d.account)}</strong></div><div><label>Rekening tujuan</label><strong>${esc(d.destination_account||'Belum tercatat')}</strong></div><div><label>Atas nama rekening tujuan</label><strong>${esc(d.destination_name||'Belum tercatat')}</strong></div><div><label>Jabatan</label><strong>${esc(d.person)}</strong></div><div><label>Email konfirmasi</label><strong>${esc(d.email)}</strong></div><div class="span-2"><label>Keterangan</label><strong>${esc(d.description||'Tidak ada keterangan tambahan.')}</strong></div></div><div class="file-card">${icon('file')}<div><strong>${esc(d.file.filename)}</strong><small>Surat untuk konfirmasi saat ini</small></div><button class="btn small" data-action="preview-file">${icon('eye')} Lihat</button><button class="btn small" data-action="download-file">${icon('download')} Unduh</button></div><div id="preview-container"></div></div></section><section class="card"><div class="card-head"><h2>Riwayat aktivitas</h2><small class="muted">${d.audit.length} aktivitas</small></div><div class="timeline">${d.audit.map(a=>`<div class="timeline-entry"><strong>${esc(a.action)}</strong>${a.notes?`<p>${esc(a.notes.replace(/Versi email \d+/g,'Pengiriman email konfirmasi'))}</p>`:''}<time>${date(a.at)} · ${esc(a.actor)}</time>${a.ip?`<p class="mono">IP ${esc(a.ip)}</p>`:''}</div>`).join('')}</div></section></div><aside class="stack"><section class="card review-card"><div class="card-head"><h3>${sol?'Keputusan SOL':'Tindak lanjut petugas'}</h3>${icon('shield')}</div><div class="card-pad stack">${d.sol_notes?notice(`<strong>Catatan SOL</strong><p>${esc(d.sol_notes)}</p>`,d.sol_status==='revision_requested'?'warn':''):''}${sol&&ready?`<p class="muted">Periksa surat dan respons nasabah sebelum memberikan keputusan.</p>${d.customer_status==='rejected'?notice('Nasabah menolak surat ini. Anda dapat meminta revisi atau menolak pengajuan.','warn'):''}<div class="field"><label for="sol-notes">Catatan pemeriksaan</label><textarea id="sol-notes" maxlength="1500" placeholder="Wajib untuk penolakan dan permintaan revisi…"></textarea></div><div class="review-actions"><button class="btn primary" data-action="sol-review" data-decision="approved" ${d.customer_status!=='confirmed'?'disabled':''}>${icon('check')} Setujui pengajuan</button><button class="btn amber" data-action="sol-review" data-decision="revision_requested">${icon('edit')} Minta revisi surat</button><button class="btn danger" data-action="sol-review" data-decision="rejected">${icon('close')} Tolak pengajuan</button></div>`:sol?notice(d.sol_status==='pending'?'Menunggu respons nasabah. Pemeriksaan tersedia setelah nasabah menyetujui atau menolak surat.':'Keputusan SOL sudah tercatat untuk surat ini.'):d.sol_status==='revision_requested'?`<p class="muted">Perbaiki surat sesuai catatan SOL, lalu kirim ulang untuk konfirmasi nasabah.</p><button class="btn primary" data-route="revise/${esc(d.id)}">${icon('edit')} Unggah revisi surat</button>`:notice(d.sol_status==='cancelled'?'Pengajuan dibatalkan. Tautan konfirmasi tidak berlaku lagi.':d.customer_status==='pending'?'Email konfirmasi sedang menunggu respons nasabah.':'Respons nasabah sudah tercatat. Pantau keputusan SOL di halaman ini.')}${!sol&&['pending','revision_requested'].includes(d.sol_status)?'<button class="btn danger" data-action="cancel-document">Batalkan pengajuan</button>':''}${sol?'<button class="btn danger" data-action="archive-document">Hapus pengajuan</button>':''}</div></section><section class="card"><div class="card-head"><h3>Pengiriman email</h3>${icon('mail')}</div><div class="card-pad stack"><div><label class="muted">Status email</label><p><strong>${esc(mailLabels[d.mail?.status]||'Belum tersedia')}</strong></p>${d.mail?.sent_at?`<small class="muted">${date(d.mail.sent_at)}</small>`:''}</div>${d.mail?.error?notice(esc(d.mail.error),'error'):''}${d.mail?.status==='local'?notice('Ini email pengujian lokal. Email belum dikirim ke alamat nasabah.','warn'):''}${state.config.mail_mode==='console'?'<button class="btn" data-route="emails">Buka kotak email lokal</button>':''}${!sol&&d.customer_status==='pending'&&d.sol_status==='pending'?'<button class="btn" data-action="resend">'+icon('refresh')+' Kirim tautan baru</button>':''}<small class="muted">${d.sol_status==='cancelled'?'Tautan konfirmasi sudah dinonaktifkan.':`Berlaku hingga ${date(d.file.expires*1000)}. Pengiriman baru membatalkan tautan lama.`}</small></div></section><section class="card"><div class="card-head"><h3>Riwayat surat</h3><small class="muted">${d.versions.length} surat</small></div>${d.versions.map(v=>`<div class="version-row">${icon("file")}<div><strong>${esc(v.filename)}</strong><small>${rupiah(v.nominal)}<br>${date(v.created)}</small></div>${v.version===d.version&&d.sol_status!=='cancelled'?'<span class="badge green">Aktif</span>':''}<button class="btn icon small" data-action="download-version" data-version="${v.version}" aria-label="Unduh surat ${esc(v.filename)}">${icon('download')}</button></div>`).join('')}</section></aside></div>`;
}
function renderCustomers() {
 $('#main').innerHTML=`<section class="card customers-card"><div class="card-head customers-card-head"><div><h1>Data Nasabah</h1><p>Kelola data dan kontak penerima konfirmasi.</p></div><div class="actions selection-actions">${state.customerDeleteMode||state.customerEditMode?'<button class="btn" data-action="cancel-customer-selection">Batal</button>':''}${!state.customerEditMode?`<button class="btn danger" id="delete-selected-customers" data-action="select-customers" aria-pressed="${state.customerDeleteMode}" ${state.customers.length?'':'disabled'}>Hapus</button>`:''}${!state.customerDeleteMode?`<button class="btn" id="edit-selected-customer" data-action="select-customer-edit" aria-pressed="${state.customerEditMode}">Edit</button>`:''}<button class="btn primary" data-action="new-customer">${icon('plus')} Tambah nasabah</button></div></div><div class="filters customer-filters"><form id="customer-search-form" class="search-box" role="search" autocomplete="off">${icon('search')}<input id="customer-list-search" name="customer_search" class="input" type="search" autocomplete="off" spellcheck="false" aria-label="Cari nama nasabah atau CIF" placeholder="Cari nama nasabah atau CIF…" value="${esc(state.customerSearch)}"></form><span id="customer-selection-count" class="customer-selection-count" aria-live="polite"></span></div><div id="customer-table"></div><div class="customer-list-footer"><span id="customer-list-count" aria-live="polite"></span><p>${icon('shield')} Gunakan email pihak yang berwenang untuk konfirmasi.</p></div></section>`;
 $('#customer-search-form').addEventListener('submit',e=>e.preventDefault());
 $('#customer-list-search').addEventListener('input',e=>{state.customerSearch=e.target.value;renderCustomerTable();});
 renderCustomerTable();
}
function renderCustomerTable() {
 const editing=state.customerEditMode;const selectable=state.customerDeleteMode||editing;
 const pending=cif=>state.customerUpdates.some(r=>r.cif===cif&&r.status==='pending');
 const query=state.customerSearch.trim().toLocaleLowerCase('id-ID');const rows=state.customers.filter(c=>c.name.toLocaleLowerCase('id-ID').includes(query)||c.cif.includes(query));
 state.customerSelected=state.customerSelected.filter(cif=>state.customers.some(c=>c.cif===cif)&&(!editing||!pending(cif)));
 $('#customer-list-count').textContent=rows.length+' dari '+state.customers.length+' nasabah';
 $('#customer-selection-count').textContent=selectable?(editing?'Pilih nasabah yang ingin diedit':'Pilih nasabah yang ingin dihapus'):'';
 const edit=$('#edit-selected-customer');if(edit)edit.disabled=!state.customers.some(c=>!pending(c.cif));
 const remove=$('#delete-selected-customers');if(remove)remove.disabled=!state.customers.length;
 $('#customer-table').innerHTML=rows.length?`<div class="table-wrap"><table class="table customer-table"><colgroup>${selectable?'<col class="customer-checkbox-col">':''}<col class="customer-cif-col"><col class="customer-name-col"><col class="customer-account-col"><col class="customer-role-col"><col class="customer-email-col"><col class="customer-phone-col"></colgroup><thead><tr>${selectable?`<th class="customer-select"><span class="visually-hidden">Pilih nasabah untuk ${editing?'diedit':'dihapus'}</span></th>`:''}<th>CIF</th><th>Nama nasabah</th><th>Nomor rekening</th><th>Jabatan</th><th>Email</th><th>Nomor HP</th></tr></thead><tbody>${rows.map(c=>`<tr class="${selectable&&state.customerSelected.includes(c.cif)?'customer-row-selected':''}" ${selectable&&(!editing||!pending(c.cif))?`data-customer-pick="${esc(c.cif)}" tabindex="0" aria-label="${editing?'Edit':'Hapus'} nasabah ${esc(c.name)}"`:''}>${selectable?`<td class="customer-select"><input type="radio" name="customer-to-select" data-customer-select="${esc(c.cif)}" ${editing&&pending(c.cif)?'disabled':''} aria-label="Pilih nasabah ${esc(c.name)}" ${state.customerSelected.includes(c.cif)?'checked':''}></td>`:''}<td class="mono">${esc(c.cif)}</td><td><strong>${esc(c.name)}</strong>${pending(c.cif)?'<small class="muted">Menunggu BOH</small>':''}</td><td class="mono">${esc(c.account)}</td><td>${esc(c.person)}</td><td>${esc(c.email)}</td><td class="${c.phone?'mono':'muted'}">${esc(c.phone||'Belum diisi')}</td></tr>`).join('')}</tbody></table></div>`:empty(query?'Nasabah tidak ditemukan':'Belum ada nasabah',query?'Coba nama atau CIF yang berbeda.':'Tambahkan nasabah untuk memulai pengajuan.');
 if(!selectable||!rows.length)return;
 const choose=cif=>{const customer=state.customers.find(c=>c.cif===cif);if(!customer||editing&&pending(cif))return;state.customerSelected=[cif];renderCustomerTable();if(editing)newCustomer(customer);else confirmCustomerDeletion([customer]);};
 document.querySelectorAll('[data-customer-select]').forEach(input=>input.addEventListener('click',()=>{if(!input.disabled)choose(input.dataset.customerSelect);}));
 document.querySelectorAll('[data-customer-pick]').forEach(row=>{
  row.addEventListener('click',e=>{if(!e.target.closest('input'))choose(row.dataset.customerPick);});
  row.addEventListener('keydown',e=>{if(e.target===row&&['Enter',' '].includes(e.key)){e.preventDefault();choose(row.dataset.customerPick);}});
 });
}
const customerFieldLabels={name:'Nama nasabah',account:'Nomor rekening',person:'Jabatan',email:'Alamat email',phone:'Nomor HP'};
const customerUpdateLabels={pending:'Menunggu BOH',approved:'Disetujui BOH',rejected:'Ditolak BOH',cancelled:'Dibatalkan'};
function customerChanges(request) {return Object.keys(customerFieldLabels).filter(key=>request.old_data[key]!==request.new_data[key]);}
function customerUpdateBadge(status) {return badge({pending:'pending',approved:'confirmed',rejected:'rejected',cancelled:'grey'}[status]||'grey',customerUpdateLabels[status]||status);}
function renderCustomerUpdates() {
 const rows=state.customerUpdates.filter(r=>state.customerUpdateFilter==='all'||r.status===state.customerUpdateFilter);
 const pending=state.customerUpdates.filter(r=>r.status==='pending').length;
 $('#main').innerHTML=`${head('UPDATE DATA','Update data','')}<section class="card"><div class="card-head customer-updates-head"><div><h2>Permintaan perubahan</h2><p>${pending} pembaruan menunggu persetujuan BOH.</p></div><select id="customer-update-filter" class="input" aria-label="Filter pembaruan nasabah"><option value="all">Semua status</option>${Object.entries(customerUpdateLabels).map(([value,label])=>`<option value="${value}" ${state.customerUpdateFilter===value?'selected':''}>${label}</option>`).join('')}</select></div>${rows.length?`<div class="table-wrap"><table class="table customer-updates-table"><thead><tr><th>Nasabah / CIF</th><th>Data yang diubah</th><th>Diajukan oleh</th><th>Status</th><th>Diajukan pada</th><th>Aksi</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.old_data.name)}</strong><small class="mono">CIF ${esc(r.cif)}</small></td><td>${customerChanges(r).map(key=>customerFieldLabels[key]).join(', ')}</td><td>${esc(r.requested_name)}</td><td>${customerUpdateBadge(r.status)}</td><td>${date(r.created)}</td><td><button class="btn small" data-action="view-customer-update" data-id="${esc(r.id)}">${state.user.role==='boh'&&r.status==='pending'?'Periksa':'Lihat'}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada pembaruan',state.customerUpdateFilter==='all'?'Permintaan perubahan dari SOL akan tampil di sini.':'Tidak ada pembaruan dengan status ini.')}</section>`;
 $('#customer-update-filter').addEventListener('change',e=>{state.customerUpdateFilter=e.target.value;renderCustomerUpdates();});
}
function viewCustomerUpdate(id) {
 const request=state.customerUpdates.find(r=>r.id===id);if(!request)return;
 const canReview=state.user.role==='boh'&&request.status==='pending';
 dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">Update data</h2><button class="btn text icon" data-action="close-dialog" aria-label="Tutup">${icon('close')}</button></div><div class="dialog-body stack"><div class="spread"><div><strong>${esc(request.old_data.name)}</strong><p class="muted">CIF ${esc(request.cif)}</p></div>${customerUpdateBadge(request.status)}</div><div class="table-wrap"><table class="table customer-change-comparison"><thead><tr><th>Data</th><th>Data sebelumnya</th><th>Usulan SOL</th></tr></thead><tbody>${customerChanges(request).map(key=>`<tr><td>${customerFieldLabels[key]}</td><td>${esc(request.old_data[key]||'Belum diisi')}</td><td><strong>${esc(request.new_data[key])}</strong></td></tr>`).join('')}</tbody></table></div><div class="field"><label for="customer-update-reason">Alasan perubahan</label><textarea id="customer-update-reason" rows="3" readonly>${esc(request.reason)}</textarea><small>${esc(request.requested_name)} · ${date(request.created)}</small></div>${canReview?'<div class="field"><label for="customer-review-notes">Catatan BOH</label><textarea id="customer-review-notes" maxlength="1500" placeholder="Wajib diisi jika menolak perubahan."></textarea></div>':request.reviewed_at?`<div class="field"><label for="customer-update-decision">Keputusan</label><textarea id="customer-update-decision" rows="3" readonly>${esc(request.review_notes||'Tidak ada catatan tambahan.')}</textarea><small>${esc(request.reviewed_name)} · ${date(request.reviewed_at)}</small></div>`:'<p class="muted">Data nasabah tetap menggunakan data lama sampai BOH menyetujui perubahan.</p>'}<div id="dialog-error" class="error-message" role="alert"></div></div><div class="dialog-footer customer-update-footer"><button class="btn" data-action="close-dialog">Tutup</button>${canReview?'<button class="btn danger" data-customer-review="rejected">Tolak</button><button class="btn primary" data-customer-review="approved">Setujui perubahan</button>':''}</div>`;
 dialog.showModal();
 dialog.querySelectorAll('[data-customer-review]').forEach(button=>button.addEventListener('click',async()=>{
  const decision=button.dataset.customerReview,notes=$('#customer-review-notes').value.trim();$('#dialog-error').textContent='';
  if(decision==='rejected'&&!notes){$('#dialog-error').textContent='Isi alasan penolakan terlebih dahulu.';$('#customer-review-notes').focus();return;}
  const buttons=dialog.querySelectorAll('[data-customer-review]');buttons.forEach(b=>b.disabled=true);
  try{await api('/customer-edit-requests/'+id+'/review',{decision,notes});await refreshData();dialog.close();renderCustomerUpdates();toast(decision==='approved'?'Pembaruan disetujui. Data nasabah sudah diperbarui.':'Pembaruan ditolak. Data nasabah tetap menggunakan data lama.');}
  catch(err){$('#dialog-error').textContent=err.message;buttons.forEach(b=>b.disabled=false);}
 }));
}
async function renderArchive(kind) {
 if(!['customers','documents'].includes(kind)){go('dashboard');return;}
 const result=await api('/'+kind+'/archived');
 if(state.route!=='archive/'+kind)return;
 const label=kind==='customers'?'nasabah':'pengajuan';
 $('#main').innerHTML=`${head('ARSIP DATA','Arsip '+label,'Pulihkan data ke daftar aktif atau hapus permanen jika sudah tidak diperlukan.',`<button class="btn" data-route="${kind==='customers'?'customers':'documents'}">${icon('left')} Kembali</button>`)}<section class="card"><div class="card-head"><h2>${result.items.length} ${label} diarsipkan</h2></div><div class="card-pad stack">${result.items.length?result.items.map(c=>{const key=c.cif||c.id;return `<div class="archive-row"><div><strong>${esc(c.name)}</strong><small class="muted">${esc(key)} · Dihapus ${date(c.archived_at)}</small></div><div class="actions"><button class="btn primary small" data-action="archive-restore" data-kind="${kind}" data-key="${esc(key)}" data-name="${esc(c.name)}">Pulihkan</button><button class="btn danger small" data-action="archive-purge" data-kind="${kind}" data-key="${esc(key)}" data-name="${esc(c.name)}">Hapus permanen</button></div></div>`;}).join(''):empty('Arsip kosong','Data yang dihapus akan muncul di sini.')}</div></section>`;
}
function confirmCustomerDeletion(selected) {
 if(!selected.length)return;
 showDialog('Hapus nasabah',`<div class="customer-delete"><p class="customer-delete-question">${selected.length===1?'Apakah Anda yakin akan menghapus nasabah ini?':'Apakah Anda yakin akan menghapus '+selected.length+' nasabah ini?'}</p><div class="customer-delete-list">${selected.map(c=>`<div class="customer-delete-item"><div><span>Nama nasabah</span><strong>${esc(c.name)}</strong></div><div><span>Nomor rekening</span><strong class="mono">${esc(c.account)}</strong></div></div>`).join('')}</div><p class="customer-delete-note">Data nasabah akan dihapus permanen. Riwayat pengajuan tetap tersimpan.</p></div>`,async()=>{await api('/customers/delete-selected',{cifs:selected.map(c=>c.cif),password:$('#action-password').value});state.customerSelected=[];state.customerDeleteMode=false;await refreshData();renderCustomers();toast('Data nasabah terpilih berhasil dihapus.');},'Hapus nasabah','danger');
}
function newCustomer(customer=null) {
 if(state.user?.role!=='sol'){toast('Hanya SOL yang dapat menambah nasabah.');return;}
 dialog.innerHTML=`<form id="customer-form"><div class="dialog-head"><h2 id="dialog-title">${customer?'Edit nasabah':'Tambah nasabah'}</h2><button type="button" class="btn text icon" data-action="close-dialog" aria-label="Tutup">${icon('close')}</button></div><div class="dialog-body stack"><div class="form-grid"><div class="field"><label for="c-cif">CIF</label><input id="c-cif" name="cif" value="${esc(customer?.cif||'')}" ${customer?'readonly':''} inputmode="numeric" pattern="[0-9]{3,30}" maxlength="30" required></div><div class="field"><label for="c-account">Nomor Rekening</label><input id="c-account" name="account" value="${esc(customer?.account||'')}" type="text" inputmode="numeric" pattern="[0-9]{15}" minlength="15" maxlength="15" title="Nomor rekening tepat 15 digit angka" required></div><div class="field span-2"><label for="c-name">Nama nasabah / perusahaan</label><input id="c-name" name="name" value="${esc(customer?.name||'')}" maxlength="250" required></div><div class="field span-2"><label for="c-person">Jabatan</label><input id="c-person" name="person" value="${esc(customer?.person||'')}" maxlength="250" required></div><div class="field span-2"><label for="c-phone">Nomor HP</label><input id="c-phone" name="phone" value="${esc(customer?.phone||'')}" type="tel" inputmode="tel" maxlength="16" pattern="(0[0-9]{9,12}|\\+?[1-9][0-9]{9,14})" placeholder="Contoh: 081234567890" title="Gunakan 10-15 digit, misalnya 081234567890 atau +6281234567890" required><small>Gunakan nomor HP nasabah atau pihak berwenang.</small></div><div class="field span-2"><label for="c-email">Alamat email konfirmasi</label><input id="c-email" type="email" name="email" value="${esc(customer?.email||'')}" maxlength="254" required></div>${customer?'<div class="field span-2"><label for="c-reason">Alasan perubahan</label><textarea id="c-reason" name="reason" maxlength="1500" required></textarea></div>':''}</div>${customer?'<p class="muted">Data diperbarui setelah BOH menyetujui perubahan.</p>':''}<div id="dialog-error" class="error-message" role="alert"></div></div><div class="dialog-footer"><button type="button" class="btn" data-action="close-dialog">Batal</button><button type="submit" class="btn primary">${customer?'Ajukan ke BOH':'Simpan nasabah'}</button></div></form>`;dialog.showModal();
 $('#customer-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('button[type=submit]',e.target);button.disabled=true;try{const payload=Object.fromEntries(new FormData(e.target));if(customer)payload.revision=customer.revision;await api(customer?'/customers/'+customer.cif+'/edit-requests':'/customers',payload);await refreshData();dialog.close();state.customerEditMode=false;state.customerDeleteMode=false;state.customerSelected=[];renderCustomers();toast(customer?'Pembaruan nasabah menunggu persetujuan BOH.':'Data nasabah berhasil disimpan.');}catch(err){$('#dialog-error').textContent=err.message;button.disabled=false;}});
}
function renderEmails() {
 if(!state.messages.find(m=>m.id===state.mailId))state.mailId=state.messages[0]?.id;
 const m=state.messages.find(m=>m.id===state.mailId);const link=m?.body.match(/https?:\/\/\S+\/#confirm\/[^\s]+/)?.[0];
 $('#main').innerHTML=`${head('PENGUJIAN ALUR EMAIL','Kotak email lokal','Pratinjau email untuk pengujian, tanpa pengiriman ke alamat nasabah.')}${notice('Mode email lokal aktif. Buka tautan konfirmasi di tab baru untuk menguji respons nasabah. Aktifkan SMTP untuk pengiriman email nyata.','warn')}<br>${m?`<div class="email-grid"><section class="card email-list">${state.messages.map(msg=>`<button class="email-item ${msg.id===m.id?'active':''}" data-mail="${esc(msg.id)}"><strong>${esc(msg.customer_name)}</strong><p>${esc(msg.doc_id)}</p><span class="badge grey">${esc(mailLabels[msg.status])}</span></button>`).join('')}</section><section class="card"><div class="card-head"><div><h2>Email konfirmasi</h2><p>${esc(m.recipient)}</p></div><button class="btn small" data-route="doc/${esc(m.doc_id)}">Detail surat</button></div><div class="card-pad stack"><div><strong>${esc(m.subject)}</strong><p class="email-meta">Kepada: ${esc(m.recipient)}<br>Dibuat: ${date(m.created)}</p></div><pre class="email-body">${esc(m.body)}</pre>${link?`<a class="btn primary" href="${esc(link)}" target="_blank" rel="noopener noreferrer">${icon('arrow')} Buka halaman konfirmasi nasabah</a>`:''}</div></section></div>`:empty('Belum ada email','Buat pengajuan terlebih dahulu. Email konfirmasi akan muncul di sini.')}`;
}
function renderSettings() {
 $('#main').innerHTML=`<div class="settings-page">${head('KEAMANAN AKUN','Pengaturan akun','Perbarui kata sandi untuk menjaga keamanan akun Anda.')}<section class="card settings-card"><div class="card-head"><div><h2>Ubah kata sandi</h2><p>${esc(state.user.name)} · ${esc(state.user.email)}</p></div><span class="settings-lock">${icon('lock')}</span></div><form id="password-form" class="card-pad stack"><div class="field"><label for="old-password">Kata sandi saat ini</label><input id="old-password" type="password" name="current" autocomplete="current-password" required></div><div class="field"><label for="new-password">Kata sandi baru</label><input id="new-password" type="password" name="password" minlength="12" autocomplete="new-password" aria-describedby="password-help" required><small id="password-help">Gunakan minimal 12 karakter dan hindari kata sandi yang dipakai di akun lain.</small></div><div class="field"><label for="repeat-password">Konfirmasi kata sandi baru</label><input id="repeat-password" type="password" minlength="12" autocomplete="new-password" required></div>${notice('Setelah kata sandi diubah, sesi di perangkat lain akan berakhir. Anda tetap masuk di perangkat ini.')}<div id="password-error" class="error-message" role="alert"></div><div class="settings-actions"><button class="btn primary" type="submit">${icon('check')} Simpan kata sandi</button></div></form></section></div>`;
 $('#password-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('button',e.target);button.disabled=true;$('#password-error').textContent='';try{if($('#new-password').value!==$('#repeat-password').value)throw new Error('Konfirmasi kata sandi belum cocok. Ketik kembali kata sandi baru Anda.');await api('/password',Object.fromEntries(new FormData(e.target)));e.target.reset();toast('Kata sandi berhasil diperbarui.');}catch(err){$('#password-error').textContent=err.message;}finally{button.disabled=false;}});
}
function showDialog(title,body,onConfirm,confirmLabel='Ya, lanjutkan',variant='primary') {
 if(variant==='danger'&&confirmLabel.startsWith('Hapus'))body+=`<form id="action-password-form" autocomplete="off"><input type="text" name="username" autocomplete="username" value="${esc(state.user.email)}" readonly class="visually-hidden" tabindex="-1" aria-hidden="true"><div class="field"><label for="action-password">Kata sandi akun SOL</label><input id="action-password" name="password" type="password" autocomplete="current-password" required><small>Masukkan kata sandi SOL Anda untuk melanjutkan penghapusan.</small></div></form>`;
 dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="btn text icon" data-action="close-dialog" aria-label="Tutup">${icon('close')}</button></div><div class="dialog-body">${body}<div id="dialog-error" class="error-message" role="alert"></div></div><div class="dialog-footer"><button class="btn" data-action="close-dialog">Batal</button><button class="btn ${variant}" id="dialog-confirm">${esc(confirmLabel)}</button></div>`;
 $('#action-password-form')?.addEventListener('submit',e=>e.preventDefault());
 dialog.showModal();$('#dialog-confirm').addEventListener('click',async()=>{const b=$('#dialog-confirm');b.disabled=true;try{await onConfirm();dialog.close();}catch(err){if($('#dialog-error'))$('#dialog-error').textContent=err.message;b.disabled=false;}});
}
async function review(decision) {
 const d=state.detail;const notes=$('#sol-notes').value.trim();if(decision!=='approved'&&!notes){$('#sol-notes').focus();toast('Isi alasan penolakan atau catatan perbaikan terlebih dahulu.',true);return;}
 const titles={approved:'Setujui pengajuan?',rejected:'Tolak pengajuan?',revision_requested:'Minta revisi surat?'};
 showDialog(titles[decision],`<p>${esc(d.id)}<br><strong>${esc(d.customer_name)} · ${rupiah(d.nominal)}</strong></p><p>${decision==='revision_requested'?'Petugas akan menerima catatan perbaikan. Surat revisi perlu dikonfirmasi ulang oleh nasabah.':'Keputusan akan dicatat dan tidak dapat diubah melalui halaman ini.'}</p>${notes?`<p>Catatan: ${esc(notes)}</p>`:''}`,async()=>{await api('/documents/'+d.id+'/review',{version:d.version,decision,notes});await refreshData();toast('Keputusan SOL berhasil dicatat.');await renderRoute();},decision==='approved'?'Ya, setujui':decision==='rejected'?'Ya, tolak':'Kirim permintaan revisi',decision==='rejected'?'danger':decision==='revision_requested'?'amber':'primary');
}
let previewUrl=null;
async function viewFile(download=false,portalToken=null) {
 if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null;}
 const blob=portalToken?await api('/portal/file',{token:portalToken},true):await api('/documents/'+state.detail.id+'/file',undefined,true);
 previewUrl=URL.createObjectURL(blob);
 if(download){const a=document.createElement('a');a.href=previewUrl;a.download=portalToken?state.portal.file.filename:state.detail.file.filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);}
 else{const mime=portalToken?state.portal.file.mime:state.detail.file.mime;$('#preview-container').innerHTML=mime==='application/pdf'?`<iframe class="file-preview" title="Pratinjau surat PDF" src="${previewUrl}"></iframe>`:`<img class="image-preview" alt="Pratinjau surat" src="${previewUrl}">`;}
}
async function renderPortal() {
 const token=routeNow().slice('confirm/'.length);state.route=routeNow();
 app.innerHTML=`<main class="portal"><div class="portal-header">${brand()}${badge('confirmed','Konfirmasi pribadi')}</div><div class="card card-pad">Memuat surat Anda…</div></main>`;
 try{const result=await api('/portal',{token});if(routeNow()!=='confirm/'+token)return;state.portal=result;state.portalToken=token;renderPortalForm();}catch(err){app.innerHTML=`<main class="portal"><div class="portal-header">${brand()}</div><section class="card result-card"><div class="success-icon">${icon('lock')}</div><h1>Tautan tidak tersedia</h1><p>${esc(err.message)}</p>${notice('Jika Anda membutuhkan surat atau tautan baru, silakan hubungi petugas yang mengirim email konfirmasi.','warn')}</section></main>`;}
}
function renderPortalForm() {
 const {document:d,file,expires}=state.portal;
 app.innerHTML=`<main class="portal"><header class="portal-header">${brand()}${badge('confirmed','Konfirmasi pribadi')}</header><div class="portal-intro"><div class="eyebrow">KONFIRMASI DOKUMEN</div><h1>Konfirmasi surat transaksi</h1><p>Yth. ${esc(d.person)}, mohon pastikan detail di bawah sesuai dengan surat yang Anda ajukan.</p></div><section class="card"><div class="card-pad"><div class="portal-amount"><small>NOMINAL TRANSAKSI</small><strong>${rupiah(d.nominal)}</strong><p>${esc(d.kind)}</p></div><div class="detail-grid"><div><label>Nama nasabah</label><strong>${esc(d.customer_name)}</strong></div><div><label>Rekening tujuan</label><strong>${esc(d.destination_account||'Belum tercatat')}</strong></div><div><label>Atas nama rekening tujuan</label><strong>${esc(d.destination_name||'Belum tercatat')}</strong></div><div><label>Jabatan</label><strong>${esc(d.person)}</strong></div><div><label>ID dokumen</label><strong class="mono">${esc(d.id)}</strong></div><div class="span-2"><label>Keterangan transaksi</label><strong>${esc(d.description||'Tidak ada keterangan tambahan.')}</strong></div></div><div class="file-card">${icon('file')}<div><strong>${esc(file.filename)}</strong><small>Surat yang dimintakan konfirmasi</small></div><button class="btn small" data-action="portal-preview">${icon('eye')} Lihat</button><button class="btn small" data-action="portal-download">${icon('download')} Unduh</button></div><div id="preview-container"></div></div><form class="form-section stack" id="portal-form"><div class="field"><label for="portal-notes">Catatan / alasan penolakan</label><textarea id="portal-notes" maxlength="1500" placeholder="Wajib jika Anda menolak surat. Jelaskan detail yang belum sesuai…"></textarea></div><label class="check"><input type="checkbox" id="portal-ack" required><span>Saya adalah pihak yang berwenang. Saya telah memeriksa surat, detail transaksi, rekening tujuan, dan nominal <strong>${rupiah(d.nominal)}</strong>.</span></label><div id="portal-error" class="error-message" role="alert"></div><div class="actions"><button type="submit" class="btn danger" name="decision" value="rejected">${icon('close')} Tolak surat</button><button type="submit" class="btn primary" name="decision" value="confirmed">${icon('check')} Setujui surat</button></div>${notice('Keputusan Anda hanya dapat dicatat satu kali untuk surat ini. Setelah Anda setuju, pengajuan akan diperiksa oleh SOL.')}</form></section><footer class="portal-footer"><p>${icon('lock')} Tautan pribadi · Jangan bagikan kepada pihak lain</p><p>Berlaku sampai ${date(expires*1000)} WIB</p><p>${esc(state.config.bank_name||'BRI VISTA')}</p></footer></main>`;
 $('#portal-form').addEventListener('submit',e=>{e.preventDefault();const decision=e.submitter?.value;if(!decision)return;const notes=$('#portal-notes').value.trim();$('#portal-error').textContent='';if(decision==='rejected'&&!notes){$('#portal-error').textContent='Tuliskan alasan penolakan agar petugas dapat menindaklanjuti.';$('#portal-notes').focus();return;}
 showDialog(decision==='confirmed'?'Setujui surat ini?':'Tolak surat ini?',`<p>${esc(d.id)}<br><strong>${rupiah(d.nominal)}</strong></p><p>Rekening tujuan: <strong>${esc(d.destination_account||'Belum tercatat')}</strong><br>Atas nama: <strong>${esc(d.destination_name||'Belum tercatat')}</strong></p><p>${decision==='confirmed'?'Anda menyatakan bahwa surat dan nominal transaksi sudah sesuai.':'Penolakan dan alasan Anda akan diteruskan kepada petugas dan SOL.'}</p>`,async()=>{await api('/portal/decision',{token:state.portalToken,decision,notes,acknowledged:$('#portal-ack').checked});renderPortalResult(decision,d);},decision==='confirmed'?'Ya, setujui surat':'Ya, tolak surat',decision==='confirmed'?'primary':'danger');
 });
}
function renderPortalResult(decision,d) {
 app.innerHTML=`<main class="portal"><header class="portal-header">${brand()}</header><section class="card result-card"><div class="success-icon">${icon(decision==='confirmed'?'check':'file')}</div><div class="eyebrow">RESPONS BERHASIL DICATAT</div><h1>${decision==='confirmed'?'Terima kasih atas konfirmasi Anda.':'Penolakan Anda telah kami terima.'}</h1><p>${esc(d.id)}<br><strong>${rupiah(d.nominal)}</strong></p><p>Rekening tujuan: <strong>${esc(d.destination_account||'Belum tercatat')}</strong><br>Atas nama: <strong>${esc(d.destination_name||'Belum tercatat')}</strong></p><p>${decision==='confirmed'?'Persetujuan surat Anda telah diteruskan kepada SOL untuk diperiksa.':'Petugas dan SOL dapat melihat penolakan beserta catatan Anda untuk ditindaklanjuti.'}</p>${notice('Tautan ini telah digunakan. Anda dapat menutup halaman ini.')}</section><footer class="portal-footer">${esc(state.config.bank_name)}</footer></main>`;
}
async function handleAction(e) {
 const target=e.target.closest('[data-route],[data-action],[data-tab],[data-mail]');if(!target)return;
 if(target.dataset.route){state.page=1;go(target.dataset.route);return;}
 if(target.dataset.tab){state.tab=target.dataset.tab;state.page=1;renderDashboard(true);return;}
 if(target.dataset.mail){state.mailId=target.dataset.mail;renderEmails();return;}
 const action=target.dataset.action;
 try{
 if(action==='page-prev'||action==='page-next'){state.page+=action==='page-next'?1:-1;renderTable();}
 else if(action==='demo'){$('#login-email').value=target.dataset.role+'@bpip.local';$('#login-password').value=target.dataset.role==='petugas'?'PetugasDemo!2026':'SolDemo!2026';}
 else if(action==='reload')location.reload();
 else if(action==='menu')$('#sidebar').classList.toggle('open');
 else if(action==='close-dialog')dialog.close();
 else if(action==='new-customer'){state.customerEditMode=false;state.customerDeleteMode=false;state.customerSelected=[];renderCustomers();newCustomer();}
 else if(action==='choose-file')$('#doc-file').click();
 else if(action==='select-customer-edit'){state.customerEditMode=true;state.customerDeleteMode=false;state.customerSelected=[];renderCustomers();}
 else if(action==='view-customer-update'){viewCustomerUpdate(target.dataset.id);}
 else if(action==='select-customers'){state.customerEditMode=false;state.customerDeleteMode=true;state.customerSelected=[];renderCustomers();}
 else if(action==='cancel-customer-selection'){state.customerDeleteMode=false;state.customerEditMode=false;state.customerSelected=[];renderCustomers();}
 else if(action==='archive-restore'||action==='archive-purge'){const kind=target.dataset.kind,key=target.dataset.key,name=target.dataset.name,purge=action==='archive-purge';showDialog(purge?'Hapus permanen?':'Pulihkan data?',`<p><strong>${esc(name)}</strong><br>${esc(key)}</p><p>${purge?(kind==='customers'?'Data master nasabah tidak dapat dipulihkan. Surat dan riwayat pengajuan lama tetap tersimpan.':'Surat dan data pengajuan dihapus permanen dan tidak dapat dipulihkan. Catatan audit pengelolaan tetap tersimpan.'):'Data ini akan kembali muncul di daftar. Tautan konfirmasi pengajuan lama tetap tidak berlaku.'}</p>${purge?`<div class="field"><label for="purge-confirmation">Ketik ${esc(key)} untuk konfirmasi</label><input id="purge-confirmation" autocomplete="off" required></div>`:''}`,async()=>{await api('/'+kind+'/'+encodeURIComponent(key)+'/'+(purge?'purge':'restore'),purge?{password:$('#action-password').value,confirmation:$('#purge-confirmation').value}:{});await refreshData();await renderArchive(kind);toast(purge?'Data dihapus permanen.':'Data dipulihkan.');},purge?'Hapus permanen':'Pulihkan',purge?'danger':'primary');}
 else if(action==='logout'){showDialog('Keluar dari ruang kerja?','<p>Anda dapat masuk kembali menggunakan akun yang sama.</p>',async()=>{await api('/logout',{});state.documents=[];state.customers=[];state.detail=null;renderLogin();},'Keluar');}
 else if(action==='refresh'){target.disabled=true;await refreshData();await renderRoute();toast('Data sudah diperbarui.');target.disabled=false;}
 else if(action==='sol-review')review(target.dataset.decision);
 else if(action==='download-execution-pdf'){target.disabled=true;try{const id=target.dataset.id||state.detail.id;const blob=await api('/documents/'+id+'/execution-pdf',undefined,true);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='konfirmasi-pelaksanaan-'+id+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('PDF pelaksanaan berhasil diunduh.');}finally{target.disabled=false;}}
 else if(action==='download-version'){target.disabled=true;const blob=await api('/documents/'+state.detail.id+'/versions/'+target.dataset.version+'/file',undefined,true);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=state.detail.versions.find(v=>String(v.version)===target.dataset.version).filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);target.disabled=false;}
 else if(action==='preview-file'||action==='download-file'){target.disabled=true;await viewFile(action==='download-file');target.disabled=false;}
 else if(action==='portal-preview'||action==='portal-download'){target.disabled=true;await viewFile(action==='portal-download',state.portalToken);target.disabled=false;}
 else if(action==='archive-document'){const d=state.detail;showDialog('Hapus pengajuan dari daftar?',`<p>${esc(d.id)} akan dipindahkan ke arsip. Surat dan riwayat tetap tersimpan dan dapat dipulihkan oleh SOL. Tautan nasabah dinonaktifkan; email yang sudah terkirim tidak dapat ditarik kembali.</p>`,async()=>{await api('/documents/'+d.id+'/archive',{version:d.version,password:$('#action-password').value});await refreshData();go('documents');toast('Pengajuan dipindahkan ke arsip.');},'Hapus pengajuan','danger');}
 else if(action==='select-documents'){state.documentDeleteMode=true;state.documentSelected=[];renderDashboard(true);}
 else if(action==='cancel-document-selection'){state.documentDeleteMode=false;state.documentSelected=[];renderDashboard(true);}
 else if(action==='archive-selected-documents'){const selected=state.documents.filter(d=>state.documentSelected.includes(d.id));if(!selected.length)return;showDialog('Hapus pengajuan',`<div class="customer-delete"><p class="customer-delete-question">Apakah Anda yakin akan menghapus ${selected.length===1?'pengajuan ini':selected.length+' pengajuan ini'}?</p><div class="customer-delete-list">${selected.map(d=>`<div class="customer-delete-item"><div><span>Nama nasabah</span><strong>${esc(d.customer_name)}</strong></div><div><span>Nomor pengajuan</span><strong class="mono">${esc(d.id)}</strong></div></div>`).join('')}</div><p class="customer-delete-note">Pengajuan dihapus dari daftar aktif. Surat dan catatan aktivitas tetap tersimpan. Tautan konfirmasi dinonaktifkan.</p></div>`,async()=>{await api('/documents/archive-selected',{documents:selected.map(d=>({id:d.id,version:d.version})),password:$('#action-password').value});state.documentSelected=[];state.documentDeleteMode=false;await refreshData();renderDashboard(true);toast('Pengajuan terpilih berhasil dihapus dari daftar.');},'Hapus pengajuan','danger');}
 else if(action==='cancel-document'){const d=state.detail;showDialog('Batalkan pengajuan?', '<p>Riwayat dan surat tetap tersimpan. Tautan konfirmasi dinonaktifkan. Email yang sudah terkirim tidak dapat ditarik kembali.</p><div class="field"><label for="cancel-notes">Alasan pembatalan</label><textarea id="cancel-notes" maxlength="1500" required></textarea></div>',async()=>{const notes=$('#cancel-notes').value.trim();if(!notes)throw new Error('Isi alasan pembatalan.');await api('/documents/'+d.id+'/cancel',{version:d.version,notes});await refreshData();await renderRoute();toast('Pengajuan dibatalkan.');},'Batalkan pengajuan');}
 else if(action==='resend'){const d=state.detail;showDialog('Kirim tautan konfirmasi baru?','<p>Tautan sebelumnya akan dibatalkan. Nasabah akan menerima email baru untuk surat yang sama.</p>',async()=>{await api('/documents/'+d.id+'/resend',{version:d.version});await refreshData();await renderRoute();toast('Email baru masuk antrean.');},'Kirim email baru');}
 }catch(err){target.disabled=false;toast(err.message,true);if(err.status===401&&!state.route.startsWith('confirm/'))renderLogin();}
}
app.addEventListener('click',handleAction);dialog.addEventListener('click',handleAction);
window.addEventListener('hashchange',()=>{if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null;}renderRoute();});
setInterval(async()=>{if(!state.user||state.route.startsWith('confirm/')||dialog.open)return;try{await refreshData();if(['dashboard','documents','history'].includes(state.route)){renderTable();if(state.route==='dashboard'){const counts=dashboardCounts(state.documents);document.querySelectorAll('[data-stat]').forEach(el=>{el.textContent=counts[el.dataset.stat];});}}else if(state.route==='customer-updates'){renderCustomerUpdates();}else if(state.route==='customers'){renderCustomerTable();}else if(state.route.startsWith('doc/')&&!$('#sol-notes')?.value){const result=await api('/documents/'+state.detail.id);if(result.document.updated!==state.detail.updated||result.document.mail?.status!==state.detail.mail?.status){state.detail=result.document;renderDetail();}}}catch(err){if(err.status===401)renderLogin();}},10000);
boot();
